package com.contenthub.api;
import com.contenthub.config.JwtService;import com.contenthub.domain.AppUser;import com.contenthub.repository.UserRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.web.bind.annotation.*;import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController{private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthController(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;}record Register(@Email @NotBlank String email,@Size(min=8)String password,@NotBlank String fullName){}record Login(@Email String email,@NotBlank String password){}@PostMapping("/register")public Map<String,String> register(@Valid @RequestBody Register r){if(users.existsByEmail(r.email()))throw new IllegalArgumentException("E-posta zaten kayıtlı");var u=users.save(new AppUser(r.email(),encoder.encode(r.password()),r.fullName(),users.count()==0?"ADMIN":"EDITOR"));return Map.of("token",jwt.create(u.getEmail()));}@PostMapping("/login")public Map<String,String> login(@Valid @RequestBody Login r){var u=users.findByEmail(r.email()).orElseThrow(()->new IllegalArgumentException("E-posta veya şifre hatalı"));if(!encoder.matches(r.password(),u.getPassword()))throw new IllegalArgumentException("E-posta veya şifre hatalı");return Map.of("token",jwt.create(u.getEmail()));}}